// ===== BEGIN INLINED DEPENDENCY: lib.rs =====
#![feature(core_intrinsics)]
#![feature(allocator_api)]
#![allow(unused_imports)]
#![allow(non_snake_case)]
#![allow(unused_assignments)]
#![allow(unused_macros)]
