        &&& self.thread_delayed_free.wf()
        &&& self.thread_delayed_free.instance@.id() == mim_instance
        &&& self.thread_delayed_free.heap_id == heap_id
        &&& self.tld_ptr.wf()
        &&& self.tld_ptr.tld_id == tld_id
    }
